package wordy

import (
	"strconv"
	"strings"
)

const prefix = "What is "

// Answer parses a simple math word problem and evaluates it.
// It returns the result and true on success, or 0 and false if the
// question is not a valid word problem.
func Answer(question string) (int, bool) {
	if !strings.HasPrefix(question, prefix) || !strings.HasSuffix(question, "?") {
		return 0, false
	}
	tokens := strings.Fields(strings.TrimSuffix(question, "?"))
	// Drop the "What" and "is" tokens.
	tokens = tokens[2:]
	if len(tokens) == 0 {
		return 0, false
	}
	return evaluate(tokens)
}

func evaluate(tokens []string) (int, bool) {
	value, ok := number(tokens[0])
	if !ok {
		return 0, false
	}
	i := 1
	for i < len(tokens) {
		op, n := op(tokens[i])
		if n == 0 {
			return 0, false
		}
		if i+n >= len(tokens) {
			return 0, false // operator without a following operand
		}
		operand, ok := number(tokens[i+n])
		if !ok {
			return 0, false
		}
		value, ok = apply(op, value, operand)
		if !ok {
			return 0, false
		}
		i += n + 1
	}
	return value, true
}
```

